preconditions.probe:
awk '
  FILENAME == ARGV[1] {
    line=$0
    if (line ~ /^[ \t]*#/ || line ~ /^[ \t]*$/) next
    eq=index(line, "=")
    if (eq == 0) next
    old=substr(line, 1, eq-1); gsub(/^[ \t]+|[ \t]+$/, "", old)
    new=substr(line, eq+1); gsub(/^[ \t]+|[ \t]+$/, "", new)
    if (old != "" && new != "") map[old]=new
    next
  }
  {
    line=$0
    if (line ~ /^[ \t]*#/ || line ~ /^[ \t]*$/) next
    eq=index(line, "=")
    if (eq == 0) next
    key=substr(line, 1, eq-1); gsub(/^[ \t]+|[ \t]+$/, "", key)
    if (key != "") present[key]=1
  }
  END {
    conflict=0
    for (old in map) {
      if (old in present) {
        new=map[old]
        if (new in present) conflict=1
        if (new in seen) conflict=1
        seen[new]=1
      }
    }
    exit conflict ? 1 : 0
  }
' config/renames.conf config/settings.conf
